head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF05970.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.gBzProcsNo;
scwin.gAcptNo;
scwin.gListProcsStatCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
    }
};
scwin.fn_list_sync = function() {
    if ($c.stf.getObjectValue(edt_SDate) == "") {
        $c.win.alert("조회일자를 입력해 주십시오.");
        edt_SDate.focus();
    }
    var vmm = $c.stf.getObjectValue(edt_SDate).substring(4, 6);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        if (vmm == "01" || vmm == "02" || vmm == "03" || vmm == "04") {
            $c.cm.setColumnProp(grd_List_1, "RECENT_01", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 2) + "년(최근)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_02", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 3) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_03", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 4) + "년(최근-2년)");
        } else {
            $c.cm.setColumnProp(grd_List_1, "RECENT_01", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 1) + "년(최근)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_02", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 2) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_03", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 3) + "년(최근-2년)");
        }
        var url = "/SectionTypeChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listSectSimulation&inputMessageId=SECT_SIMULATION_INOUT";
        url += "&LIST_DD=" + $c.stf.getObjectValue(edt_SDate);
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else {
        if (vmm == "01" || vmm == "02" || vmm == "03" || vmm == "04") {
            $c.cm.setColumnProp(grd_List_2, "RECENT_01", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 2) + "년(최근)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_02", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 3) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_03", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 4) + "년(최근-2년)");
        } else {
            $c.cm.setColumnProp(grd_List_2, "RECENT_01", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 1) + "년(최근)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_02", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 2) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_03", "name", (eval($c.stf.getObjectValue(edt_SDate).substring(0, 4)) - 3) + "년(최근-2년)");
        }
        var url = "/SectionTypeChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listSectSimulationHist&inputMessageId=SECT_SIMULATION_INOUT";
        url += "&LIST_DD=" + $c.stf.getObjectValue(edt_SDate);
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_OpenDetail = async function(row) {
    await $c.frame.CreateDialogFrame("ULDSTF05971", "/lstproc/ULDSTF05971.gfm", "소속부변경", 200, 50, 720, 420, "window");
};
scwin.gform_onload = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    $c.cm.PanelToGroupBox(panel_Top);
    $c.cm.setColumnProp(grd_List_1, "REGULAR_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_1, "NONSCHE_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_1, "SECT_TP_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_1, "ISUR_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_2, "REGULAR_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_2, "NONSCHE_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_2, "SECT_TP_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_2, "ISUR_CD", "Show", false);

    //fn_list_sync() ;

};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "소속부변경 시뮬레이션", "", "8");
    } else {
        $c.data.downloadGridViewExcel(grd_List_2, "소속부변경 정기심사이력", "", "8");
    }
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
